var CATEGORIAS_ITENS = ["Armas Simples","Armas Marciais","Armas Exóticas","Armas de Fogo","Munições","Armaduras Leves","Armaduras Pesadas","Escudos","Equipamento de Aventura","Ferramentas","Vestuário","Esotéricos","Alquímicos — Preparados","Alquímicos — Catalisadores","Alquímicos — Venenos","Alimentação","Animais","Veículos"];
var ITENS_LIVRO = [
  {"id":"adaga","nome":"Adaga","cat":"Armas Simples","tipo":"Arma","preco":2,"esp":1,"desc":"Arma simples · Corpo a corpo (leves) · Dano 1d4 · Crítico 19/x2 · Alcance curto · Perfuração\nEsta faca afiada é usada por muitos habitantes adultos do Reinado, embora seja favorita de ladrões e assassinos, por ser facilmente escondida (fornece +5 em testes de Ladinagem para ocultá-la). Quando ataca com uma adaga, você pode usar sua Destreza em vez de Força nos testes de ataque. Uma adaga pode ser arremessada."},
  {"id":"espada-curta","nome":"Espada Curta","cat":"Armas Simples","tipo":"Arma","preco":10,"esp":1,"desc":"Arma simples · Corpo a corpo (leves) · Dano 1d6 · Crítico 19/x2 · Perfuração\nO tipo mais comum de espada, usada por guardas ou como arma secundária de guerreiros mais capazes. Mede entre 40 e 50cm."},
  {"id":"foice","nome":"Foice","cat":"Armas Simples","tipo":"Arma","preco":4,"esp":1,"desc":"Arma simples · Corpo a corpo (leves) · Dano 1d6 · Crítico 20/x3 · Corte\nOriginalmente um instrumento agrícola, consiste de uma lâmina curva presa a um cabo de madeira. Uma arma tradicional de druidas."},
  {"id":"clava","nome":"Clava","cat":"Armas Simples","tipo":"Arma","preco":0,"esp":1,"desc":"Arma simples · Corpo a corpo (uma mão) · Dano 1d6 · Crítico 20/x2 · Impacto\nUm pedaço de madeira empunhado como arma, geralmente usado por bárbaros ou criaturas brutais — ou como arma improvisada, como um galho de árvore ou pedaço de mobília. Sendo fácil de conseguir, seu preço é zero."},
  {"id":"lanca","nome":"Lança","cat":"Armas Simples","tipo":"Arma","preco":2,"esp":1,"desc":"Arma simples · Corpo a corpo (uma mão) · Dano 1d6 · Crítico 20/x2 · Alcance curto · Perfuração\nQualquer arma feita com uma haste de madeira e uma ponta afiada, natural ou metálica. Por sua facilidade de fabricação, é muito comum entre orcs, kobolds, trogloditas e outras raças menos civilizadas. Uma lança pode ser arremessada."},
  {"id":"maca","nome":"Maça","cat":"Armas Simples","tipo":"Arma","preco":12,"esp":1,"desc":"Arma simples · Corpo a corpo (uma mão) · Dano 1d8 · Crítico 20/x2 · Impacto\nBastão com um peso cheio de protuberâncias na ponta, a maça é usada por clérigos que fazem votos de não derramar sangue. De fato, um golpe de maça nem sempre derrama sangue, mas esmaga ossos."},
  {"id":"bordao","nome":"Bordão","cat":"Armas Simples","tipo":"Arma","preco":0,"esp":2,"desc":"Arma simples · Corpo a corpo (duas mãos) · Dano 1d6/1d6 · Crítico 20/x2 · Impacto\nUm cajado apreciado por viajantes e camponeses por sua praticidade e fácil acesso (seu preço é zero). O bordão é uma arma dupla."},
  {"id":"pique","nome":"Pique","cat":"Armas Simples","tipo":"Arma","preco":2,"esp":2,"desc":"Arma simples · Corpo a corpo (duas mãos) · Dano 1d8 · Crítico 20/x2 · Perfuração\nEssencialmente uma lança muito longa. O pique é uma arma alongada."},
  {"id":"tacape","nome":"Tacape","cat":"Armas Simples","tipo":"Arma","preco":0,"esp":2,"desc":"Arma simples · Corpo a corpo (duas mãos) · Dano 1d10 · Crítico 20/x2 · Impacto\nVersão maior e/ou com pregos de uma clava. Usado por bárbaros e humanoides bestiais, não é uma arma elegante, mas faz o serviço."},
  {"id":"azagaia","nome":"Azagaia","cat":"Armas Simples","tipo":"Arma","preco":1,"esp":1,"desc":"Arma simples · Ataque à distância (uma mão) · Dano 1d6 · Crítico 20/x2 · Alcance médio · Perfuração\nUma lança leve e flexível, própria para arremesso. Pode ser usada como arma corpo a corpo, mas você sofre uma penalidade de –5 no teste de ataque."},
  {"id":"besta-leve","nome":"Besta Leve","cat":"Armas Simples","tipo":"Arma","preco":35,"esp":1,"desc":"Arma simples · Ataque à distância (uma mão) · Dano 1d8 · Crítico 19/x2 · Alcance médio · Perfuração\nUm arco montado sobre uma coronha de madeira com um gatilho, a besta leve é uma arma que dispara virotes com grande potência. Recarregar uma besta leve é uma ação de movimento."},
  {"id":"funda","nome":"Funda","cat":"Armas Simples","tipo":"Arma","preco":0,"esp":1,"desc":"Arma simples · Ataque à distância (uma mão) · Dano 1d4 · Crítico 20/x2 · Alcance médio · Impacto\nUma simples tira de couro usada para arremessar pedras polidas. Na falta de munição adequada, pode disparar pedras comuns, mas o dano é reduzido em um passo. Recarregar uma funda é uma ação de movimento. Ao contrário de outras armas de disparo, você aplica sua Força a rolagens de dano com uma funda."},
  {"id":"arco-curto","nome":"Arco Curto","cat":"Armas Simples","tipo":"Arma","preco":30,"esp":2,"desc":"Arma simples · Ataque à distância (duas mãos) · Dano 1d6 · Crítico 20/x3 · Alcance médio · Perfuração\nUma arma antiga e comum, este arco é usado primariamente como ferramenta de caça, embora seja usado como arma de guerra por milícias, bandidos e exércitos menos equipados. Pode ser usado montado."},
  {"id":"machadinha","nome":"Machadinha","cat":"Armas Marciais","tipo":"Arma","preco":6,"esp":1,"desc":"Arma marcial · Corpo a corpo (leves) · Dano 1d6 · Crítico 20/x3 · Alcance curto · Corte\nFerramenta útil para cortar madeira e também inimigos. Uma machadinha pode ser arremessada."},
  {"id":"cimitarra","nome":"Cimitarra","cat":"Armas Marciais","tipo":"Arma","preco":15,"esp":1,"desc":"Arma marcial · Corpo a corpo (uma mão) · Dano 1d6 · Crítico 18/x2 · Corte\nEspada com a lâmina curva e muito afiada. A cimitarra é uma arma ágil."},
  {"id":"espada-longa","nome":"Espada Longa","cat":"Armas Marciais","tipo":"Arma","preco":15,"esp":1,"desc":"Arma marcial · Corpo a corpo (uma mão) · Dano 1d8 · Crítico 19/x2 · Corte\nArma típica de soldados e guerreiros, esta espada de dois gumes tem lâmina reta medindo entre 80cm e 1m."},
  {"id":"florete","nome":"Florete","cat":"Armas Marciais","tipo":"Arma","preco":20,"esp":1,"desc":"Arma marcial · Corpo a corpo (uma mão) · Dano 1d6 · Crítico 18/x2 · Perfuração\nA lâmina leve e fina desta espada torna a arma muito precisa. O florete é uma arma ágil."},
  {"id":"machado-batalha","nome":"Machado de Batalha","cat":"Armas Marciais","tipo":"Arma","preco":10,"esp":1,"desc":"Arma marcial · Corpo a corpo (uma mão) · Dano 1d8 · Crítico 20/x3 · Corte\nAdaptado do machado de lenhador, este não é um instrumento para corte de árvores, mas sim uma arma capaz de causar ferimentos terríveis."},
  {"id":"mangual","nome":"Mangual","cat":"Armas Marciais","tipo":"Arma","preco":8,"esp":1,"desc":"Arma marcial · Corpo a corpo (uma mão) · Dano 1d8 · Crítico 20/x2 · Impacto\nUma haste metálica ligada a uma corrente com uma esfera de aço na ponta, que pode se enroscar na arma do adversário. O mangual é uma arma versátil, fornecendo +2 em testes para desarmar."},
  {"id":"martelo-guerra","nome":"Martelo de Guerra","cat":"Armas Marciais","tipo":"Arma","preco":12,"esp":1,"desc":"Arma marcial · Corpo a corpo (uma mão) · Dano 1d8 · Crítico 20/x3 · Impacto\nOutra ferramenta adaptada para combate, esta é a arma favorita de quase todos os anões que não usam machados."},
  {"id":"picareta","nome":"Picareta","cat":"Armas Marciais","tipo":"Arma","preco":8,"esp":1,"desc":"Arma marcial · Corpo a corpo (uma mão) · Dano 1d6 · Crítico 20/x4 · Perfuração\nUsada por mineradores, esta ferramenta quebra pedras com facilidade. Imagine o que pode fazer com carne e osso!"},
  {"id":"tridente","nome":"Tridente","cat":"Armas Marciais","tipo":"Arma","preco":15,"esp":1,"desc":"Arma marcial · Corpo a corpo (uma mão) · Dano 1d8 · Crítico 20/x2 · Alcance curto · Perfuração\nUma lança com três pontas, favorita de povos marinhos e gladiadores e própria para prender as pernas do oponente. O tridente é uma arma versátil, fornecendo +2 em testes para derrubar. Um tridente pode ser arremessado."},
  {"id":"alabarda","nome":"Alabarda","cat":"Armas Marciais","tipo":"Arma","preco":10,"esp":2,"desc":"Arma marcial · Corpo a corpo (duas mãos) · Dano 1d10 · Crítico 20/x3 · Corte/perfuração\nUma haste de madeira com 2m de comprimento e uma lâmina de machado na ponta. A alabarda é uma arma alongada."},
  {"id":"alfange","nome":"Alfange","cat":"Armas Marciais","tipo":"Arma","preco":75,"esp":2,"desc":"Arma marcial · Corpo a corpo (duas mãos) · Dano 2d4 · Crítico 18/x2 · Corte\nUma versão maior da cimitarra, esta espada de lâmina larga e curva é bastante usada por guerreiros do Deserto da Perdição."},
  {"id":"gadanho","nome":"Gadanho","cat":"Armas Marciais","tipo":"Arma","preco":18,"esp":2,"desc":"Arma marcial · Corpo a corpo (duas mãos) · Dano 2d4 · Crítico 20/x4 · Corte\nOutra ferramenta agrícola, o gadanho é uma versão maior da foice, para uso com as duas mãos. Foi criada para ceifar cereais, mas também pode ceifar vidas."},
  {"id":"lanca-montada","nome":"Lança Montada","cat":"Armas Marciais","tipo":"Arma","preco":10,"esp":2,"desc":"Arma marcial · Corpo a corpo (duas mãos) · Dano 1d8 · Crítico 20/x3 · Perfuração\nA lança montada é uma arma alongada. Se você estiver montado, pode usá-la com apenas uma mão. Além disso, quando usada numa investida montada, causa +2d8 pontos de dano (note que dados extras não são multiplicados em caso de acerto crítico)."},
  {"id":"machado-guerra","nome":"Machado de Guerra","cat":"Armas Marciais","tipo":"Arma","preco":20,"esp":2,"desc":"Arma marcial · Corpo a corpo (duas mãos) · Dano 1d12 · Crítico 20/x3 · Corte\nEste imenso machado de lâmina dupla é uma arma extremamente perigosa."},
  {"id":"marreta","nome":"Marreta","cat":"Armas Marciais","tipo":"Arma","preco":20,"esp":2,"desc":"Arma marcial · Corpo a corpo (duas mãos) · Dano 3d4 · Crítico 20/x2 · Impacto\nUma haste de madeira resistente com uma pesada cabeça de metal ou pedra."},
  {"id":"montante","nome":"Montante","cat":"Armas Marciais","tipo":"Arma","preco":50,"esp":2,"desc":"Arma marcial · Corpo a corpo (duas mãos) · Dano 2d6 · Crítico 19/x2 · Corte\nEnorme e pesada, esta espada de 1,5m de comprimento é uma arma poderosa."},
  {"id":"arco-longo","nome":"Arco Longo","cat":"Armas Marciais","tipo":"Arma","preco":100,"esp":2,"desc":"Arma marcial · Ataque à distância (duas mãos) · Dano 1d8 · Crítico 20/x3 · Alcance médio · Perfuração\nEste arco reforçado tem a altura de uma pessoa. Ao contrário da versão curta, é primariamente uma arma de guerra. Por ter uma puxada pesada, permite que você aplique sua Força às rolagens de dano (ao contrário de outras armas de disparo). Porém, um arco longo não pode ser usado se você estiver montado."},
  {"id":"besta-pesada","nome":"Besta Pesada","cat":"Armas Marciais","tipo":"Arma","preco":50,"esp":2,"desc":"Arma marcial · Ataque à distância (duas mãos) · Dano 1d12 · Crítico 19/x2 · Alcance médio · Perfuração\nVersão maior e mais potente da besta leve. Recarregar uma besta pesada é uma ação padrão."},
  {"id":"chicote","nome":"Chicote","cat":"Armas Exóticas","tipo":"Arma","preco":2,"esp":1,"desc":"Arma exótica · Corpo a corpo (uma mão) · Dano 1d3 · Crítico 20/x2 · Corte\nEsta arma pode ser usada para atacar inimigos a até 4,5m e pode se enroscar nas mãos, pernas ou armas de seus adversários. O chicote é uma arma ágil e versátil, fornecendo +2 em testes para derrubar ou desarmar."},
  {"id":"espada-bastarda","nome":"Espada Bastarda","cat":"Armas Exóticas","tipo":"Arma","preco":35,"esp":1,"desc":"Arma exótica · Corpo a corpo (uma mão) · Dano 1d10/1d12 · Crítico 19/x2 · Corte\nMaior e mais pesada que a espada longa, esta arma é tradicionalmente usada pelos cavaleiros de Bielefeld. A espada bastarda é uma arma adaptável. É muito grande para ser usada com uma só mão sem treinamento especial; por isso é uma arma exótica. Ela pode ser usada como uma arma marcial de duas mãos."},
  {"id":"katana","nome":"Katana","cat":"Armas Exóticas","tipo":"Arma","preco":100,"esp":1,"desc":"Arma exótica · Corpo a corpo (uma mão) · Dano 1d8/1d10 · Crítico 19/x2 · Corte\nA espada tradicional do samurai tem lâmina levemente curva e apenas um gume. A katana é uma arma adaptável e ágil. É muito grande para ser empunhada com uma só mão sem treinamento especial; por isso, é uma arma exótica. Ela pode ser usada como uma arma marcial de duas mãos."},
  {"id":"machado-anao","nome":"Machado Anão","cat":"Armas Exóticas","tipo":"Arma","preco":30,"esp":1,"desc":"Arma exótica · Corpo a corpo (uma mão) · Dano 1d10 · Crítico 20/x3 · Corte\nA arma preferida de onze entre dez guerreiros anões. Um machado anão é muito grande para ser usado com uma só mão sem treinamento especial; por isso é uma arma exótica. Ele pode ser usado como uma arma marcial de duas mãos."},
  {"id":"corrente-espinhos","nome":"Corrente de Espinhos","cat":"Armas Exóticas","tipo":"Arma","preco":25,"esp":2,"desc":"Arma exótica · Corpo a corpo (duas mãos) · Dano 2d4/2d4 · Crítico 19/x2 · Corte\nEsta arma pode ser usada para atacar inimigos a até 4,5m e pode se enroscar nas mãos, pernas ou armas de seus adversários. A corrente de espinhos é uma arma ágil, dupla e versátil, fornecendo +2 em testes para derrubar ou desarmar."},
  {"id":"machado-taurico","nome":"Machado Táurico","cat":"Armas Exóticas","tipo":"Arma","preco":50,"esp":2,"desc":"Arma exótica · Corpo a corpo (duas mãos) · Dano 2d8 · Crítico 20/x3 · Corte\nUma haste comprida com uma lâmina extremamente grossa na ponta, esta é uma arma ancestral dos minotauros. Um machado táurico é uma arma desbalanceada. Além disso, é muito grande para ser usado sem treinamento especial; por isso, é uma arma exótica."},
  {"id":"rede","nome":"Rede","cat":"Armas Exóticas","tipo":"Arma","preco":20,"esp":1,"desc":"Arma exótica · Ataque à distância (uma mão) · Alcance curto\nA rede tem pequenos dentes em sua trama e uma corda para controlar os inimigos presos. Se você acertar um ataque com a rede, não causa dano. Em vez disso, a vítima fica enredada (deslocamento reduzido à metade, não pode correr nem fazer investidas e sofre –2 na Defesa e em testes de ataque). Enquanto você estiver segurando a corda, sempre que a vítima se mover você pode fazer um teste de Força oposto contra ela como uma reação. Se você vencer, a vítima só pode se mover até o limite da corda (alcance curto). A vítima pode se soltar com uma ação completa e um teste de Força ou Acrobacia (CD 20). A rede tem 5 pontos de vida e, se rasgar, qualquer criatura enredada se solta automaticamente. A rede só pode ser usada contra criaturas no máximo uma categoria de tamanho maior que você."},
  {"id":"pistola","nome":"Pistola","cat":"Armas de Fogo","tipo":"Arma","preco":250,"esp":1,"desc":"Arma de fogo · Ataque à distância (leve) · Dano 2d6 · Crítico 19/x3 · Alcance curto · Perfuração\nA arma de fogo mais comum. Recarregar uma pistola é uma ação padrão."},
  {"id":"mosquete","nome":"Mosquete","cat":"Armas de Fogo","tipo":"Arma","preco":500,"esp":2,"desc":"Arma de fogo · Ataque à distância (duas mãos) · Dano 2d8 · Crítico 19/x3 · Alcance médio · Perfuração\nUma arma de fogo de uso difícil, mas com poder devastador. Recarregar um mosquete é uma ação padrão."},
  {"id":"balas","nome":"Balas (20)","cat":"Munições","tipo":"Munição","preco":20,"esp":1,"desc":"Uma bolsa com 20 balas (pequenas esferas de chumbo) e pólvora. Recarregar uma pistola ou um mosquete é uma ação padrão."},
  {"id":"flechas","nome":"Flechas (20)","cat":"Munições","tipo":"Munição","preco":1,"esp":1,"desc":"Uma aljava com 20 flechas, hastes de madeira com ponta metálica e penas para estabilizar o voo. Recarregar um arco com uma flecha é uma ação livre."},
  {"id":"pedras","nome":"Pedras (20)","cat":"Munições","tipo":"Munição","preco":0.5,"esp":1,"desc":"Um saco de couro com 20 pedras polidas. Recarregar uma funda com uma pedra de qualquer tipo é uma ação de movimento."},
  {"id":"virotes","nome":"Virotes (20)","cat":"Munições","tipo":"Munição","preco":2,"esp":1,"desc":"Uma aljava com 20 setas de madeira. Recarregar uma besta leve é uma ação de movimento; já recarregar uma besta pesada é uma ação padrão."},
  {"id":"armadura-acolchoada","nome":"Armadura Acolchoada","cat":"Armaduras Leves","tipo":"Armadura","preco":5,"esp":2,"def":1,"slot":"armadura","desc":"Armadura leve · Bônus na Defesa +1 · Penalidade de armadura 0\nUma túnica almofadada feita em linho ou lã. É a armadura mais leve, mas protege todo o corpo, fornecendo +2 em Fortitude."},
  {"id":"armadura-couro","nome":"Armadura de Couro","cat":"Armaduras Leves","tipo":"Armadura","preco":20,"esp":2,"def":2,"slot":"armadura","desc":"Armadura leve · Bônus na Defesa +2 · Penalidade de armadura 0\nO peitoral desta armadura é feito de couro curtido em óleo fervente, para ficar mais rígido, enquanto as demais partes são feitas de couro flexível."},
  {"id":"couro-batido","nome":"Couro Batido","cat":"Armaduras Leves","tipo":"Armadura","preco":35,"esp":2,"def":3,"slot":"armadura","desc":"Armadura leve · Bônus na Defesa +3 · Penalidade de armadura –1\nVersão mais pesada da armadura de couro, reforçada com rebites de metal."},
  {"id":"gibao-peles","nome":"Gibão de Peles","cat":"Armaduras Leves","tipo":"Armadura","preco":25,"esp":2,"def":4,"slot":"armadura","desc":"Armadura leve · Bônus na Defesa +4 · Penalidade de armadura –3\nUsada principalmente por bárbaros e selvagens, esta armadura é formada por várias camadas de peles e couro de animais."},
  {"id":"couraca","nome":"Couraça","cat":"Armaduras Leves","tipo":"Armadura","preco":500,"esp":2,"def":5,"slot":"armadura","desc":"Armadura leve · Bônus na Defesa +5 · Penalidade de armadura –4\nA mais robusta das armaduras leves, formada por uma placa metálica que protege o peito e as costas, presa sobre um casaco de couro."},
  {"id":"brunea","nome":"Brunea","cat":"Armaduras Pesadas","tipo":"Armadura","preco":50,"esp":5,"def":5,"slot":"armadura","desc":"Armadura pesada · Bônus na Defesa +5 · Penalidade de armadura –2\nColete de couro coberto com plaquetas de metal sobrepostas, como escamas de um peixe. Por ser barata de produzir, é a armadura mais utilizada no Reinado por soldados de infantaria e guardas de castelo.\nArmadura pesada: você não soma a Destreza na Defesa e seu deslocamento é reduzido em 3m. Vestir ou remover leva cinco minutos; dormir de armadura pesada deixa você fatigado pelo dia."},
  {"id":"cota-malha","nome":"Cota de Malha","cat":"Armaduras Pesadas","tipo":"Armadura","preco":150,"esp":5,"def":6,"slot":"armadura","desc":"Armadura pesada · Bônus na Defesa +6 · Penalidade de armadura –2\nLonga veste de anéis metálicos interligados, formando uma malha flexível e resistente, que vai até os joelhos.\nArmadura pesada: você não soma a Destreza na Defesa e seu deslocamento é reduzido em 3m. Vestir ou remover leva cinco minutos; dormir de armadura pesada deixa você fatigado pelo dia."},
  {"id":"loriga-segmentada","nome":"Loriga Segmentada","cat":"Armaduras Pesadas","tipo":"Armadura","preco":250,"esp":5,"def":7,"slot":"armadura","desc":"Armadura pesada · Bônus na Defesa +7 · Penalidade de armadura –3\nComposta por tiras horizontais de metal, esta armadura pesada é muito utilizada por legionários do Império de Tauron.\nArmadura pesada: você não soma a Destreza na Defesa e seu deslocamento é reduzido em 3m. Vestir ou remover leva cinco minutos; dormir de armadura pesada deixa você fatigado pelo dia."},
  {"id":"meia-armadura","nome":"Meia Armadura","cat":"Armaduras Pesadas","tipo":"Armadura","preco":600,"esp":5,"def":8,"slot":"armadura","desc":"Armadura pesada · Bônus na Defesa +8 · Penalidade de armadura –4\nUma cota de malha reforçada com placas de metal.\nArmadura pesada: você não soma a Destreza na Defesa e seu deslocamento é reduzido em 3m. Vestir ou remover leva cinco minutos; dormir de armadura pesada deixa você fatigado pelo dia."},
  {"id":"armadura-completa","nome":"Armadura Completa","cat":"Armaduras Pesadas","tipo":"Armadura","preco":3000,"esp":5,"def":10,"slot":"armadura","desc":"Armadura pesada · Bônus na Defesa +10 · Penalidade de armadura –5\nA mais forte e pesada das armaduras, formada por placas de metal forjadas e encaixadas de modo a cobrir o corpo inteiro. Inclui uma túnica acolchoada para ser usada sob as placas. Correias e fivelas distribuem o peso da armadura pelo corpo inteiro. Esta armadura precisa ser feita sob medida para cada usuário; um ferreiro cobra T$ 200 para adaptar uma armadura completa a um novo usuário.\nArmadura pesada: você não soma a Destreza na Defesa e seu deslocamento é reduzido em 3m. Vestir ou remover leva cinco minutos; dormir de armadura pesada deixa você fatigado pelo dia."},
  {"id":"escudo-leve","nome":"Escudo Leve","cat":"Escudos","tipo":"Escudo","preco":5,"esp":1,"def":1,"slot":"escudo","desc":"Escudo · Bônus na Defesa +1 · Penalidade de armadura –1\nTipicamente feito de madeira, este escudo é amarrado no antebraço, deixando a mão livre. Você pode carregar um objeto na mão que empunha o escudo, mas não manusear uma arma."},
  {"id":"escudo-pesado","nome":"Escudo Pesado","cat":"Escudos","tipo":"Escudo","preco":15,"esp":2,"def":2,"slot":"escudo","desc":"Escudo · Bônus na Defesa +2 · Penalidade de armadura –2\nNormalmente feito de aço, este escudo é preso ao antebraço e também deve ser empunhado com firmeza, impedindo o usuário de usar aquela mão."},
  {"id":"agua-benta","nome":"Água Benta","cat":"Equipamento de Aventura","tipo":"Equipamento","preco":10,"esp":0.5,"desc":"Produzida com a magia Abençoar Alimentos, esta água sagrada é um poderoso recurso na luta contra o mal. Para usar a água benta, você gasta uma ação padrão e escolhe um morto-vivo ou abissal em alcance curto (a água benta é inofensiva contra outras criaturas). O alvo sofre 2d10 pontos de dano de luz (Reflexos CD Sab reduz à metade)."},
  {"id":"algemas","nome":"Algemas","cat":"Equipamento de Aventura","tipo":"Equipamento","preco":15,"esp":1,"desc":"Um par de algemas para criaturas Médias. Prender uma criatura que não esteja indefesa exige empunhar a algema, agarrar o alvo (veja “Manobras de Combate”, no Capítulo 5) e vencer um novo teste de agarrar contra ela. Você pode prender os dois pulsos da pessoa (–5 em testes que exijam o uso das mãos, impede conjuração) ou um dos pulsos dela em um objeto imóvel adjacente, caso haja, para impedir que ela se mova. Escapar das algemas exige uma ação completa e um teste de Acrobacia contra CD 30 ou de Força contra CD 25 — ou ter as chaves..."},
  {"id":"arpeu","nome":"Arpéu","cat":"Equipamento de Aventura","tipo":"Equipamento","preco":5,"esp":1,"desc":"Um gancho de aço amarrado na ponta de uma corda para se fixar em muros, janelas, parapeitos de prédios... Prender um arpéu exige um teste de Pontaria (CD 15). Subir um muro com a ajuda de uma corda fornece +5 no teste de Atletismo."},
  {"id":"bandoleira-pocoes","nome":"Bandoleira de Poções","cat":"Equipamento de Aventura","tipo":"Equipamento","preco":20,"esp":1,"desc":"Um cinto de couro com bolsos que comportam pequenos frascos. Se você estiver vestindo uma bandoleira, pode sacar itens alquímicos e poções como uma ação livre."},
  {"id":"barraca","nome":"Barraca","cat":"Equipamento de Aventura","tipo":"Equipamento","preco":10,"esp":1,"desc":"Esta barraca de lona conta como um saco de dormir para duas pessoas e fornece +2 em testes de Sobrevivência para acampar."},
  {"id":"corda","nome":"Corda","cat":"Equipamento de Aventura","tipo":"Equipamento","preco":1,"esp":1,"desc":"Um rolo com 10 metros de corda de cânhamo, o mesmo tipo usado em navios. Possui diversas utilidades: pode ajudar a descer um buraco ou muro (+5 em testes de Atletismo nessas situações), amarrar pessoas etc. Dar um nó firme ou especial (por exemplo, capaz de deslizar, se desfazer com um puxão etc.) exige um teste de Destreza (CD 15)."},
  {"id":"espelho","nome":"Espelho","cat":"Equipamento de Aventura","tipo":"Equipamento","preco":10,"esp":1,"desc":"Este pequeno espelho possui diversas utilidades: observar cantos, fazer sinais de luz e, claro, garantir que você esteja apresentável."},
  {"id":"lampiao","nome":"Lampião","cat":"Equipamento de Aventura","tipo":"Equipamento","preco":7,"esp":1,"desc":"Um cilindro com uma alça e duas portinholas. Uma chama alimentada por óleo é acesa dentro do cilindro e uma das portinholas aberta deixa a luz sair. Acender um lampião é uma ação padrão e sua luz ilumina um raio com 15m. Carregar um lampião com óleo é uma ação padrão e ele dura uma cena."},
  {"id":"mochila","nome":"Mochila","cat":"Equipamento de Aventura","tipo":"Equipamento","preco":2,"esp":0,"desc":"Uma bolsa de lona com tiras para ser carregada nas costas. Não conta como item vestido."},
  {"id":"mochila-aventureiro","nome":"Mochila de Aventureiro","cat":"Equipamento de Aventura","tipo":"Equipamento","preco":50,"esp":0,"desc":"Feita de couro resistente, esta mochila é repleta de bolsos para prender equipamento. Vestir uma mochila de aventureiro aumenta sua capacidade de carga em 2 espaços (ela própria não gasta um espaço)."},
  {"id":"oleo","nome":"Óleo","cat":"Equipamento de Aventura","tipo":"Equipamento","preco":0.1,"esp":0.5,"desc":"Um frasco com óleo inflamável para lampião. Você pode atirar o frasco em uma criatura em alcance curto com uma ação padrão. Se ela sofrer dano de fogo até o fim do seu próximo turno, sofre 1d6 pontos de dano extra e fica em chamas."},
  {"id":"organizador-pergaminhos","nome":"Organizador de Pergaminhos","cat":"Equipamento de Aventura","tipo":"Equipamento","preco":25,"esp":1,"desc":"Um estojo de madeira ou couro rígido. Se você estiver vestindo um organizador de pergaminhos, pode sacar pergaminhos como uma ação livre."},
  {"id":"pe-cabra","nome":"Pé de Cabra","cat":"Equipamento de Aventura","tipo":"Equipamento","preco":2,"esp":1,"desc":"Esta barra de ferro fornece +5 em testes de Força para abrir portas, janelas e baús fechados. Um pé de cabra pode ser usado como arma, com as estatísticas de uma clava."},
  {"id":"saco-dormir","nome":"Saco de Dormir","cat":"Equipamento de Aventura","tipo":"Equipamento","preco":1,"esp":1,"desc":"Um colchão com uma coberta fina o bastante para ser enrolada e amarrada, é especialmente útil para aventureiros, que nunca sabem onde vão passar a noite. Dormir ao relento sem um acampamento e um saco de dormir diminui sua recuperação de PV e PM (veja a página 106)."},
  {"id":"simbolo-sagrado","nome":"Símbolo Sagrado","cat":"Equipamento de Aventura","tipo":"Equipamento","preco":5,"esp":1,"desc":"Um medalhão de madeira ou metal com o símbolo de uma divindade. Se você estiver vestindo (normalmente com uma corrente ao redor do pescoço) ou empunhando o símbolo sagrado de um deus do qual é devoto, recebe +1 em testes de resistência."},
  {"id":"tocha","nome":"Tocha","cat":"Equipamento de Aventura","tipo":"Equipamento","preco":0.1,"esp":1,"desc":"Um bastão de madeira com algum combustível na ponta (geralmente trapos embebidos em parafina). Acender uma tocha é uma ação padrão. Ela ilumina um raio de 9m e dura uma cena. Pode ser usada como uma arma simples leve (dano 1d4 de impacto mais 1 de fogo, crítico x2)."},
  {"id":"vara-madeira","nome":"Vara de Madeira (3m)","cat":"Equipamento de Aventura","tipo":"Equipamento","preco":0.2,"esp":1,"desc":"Uma haste com 3m de comprimento. Útil para alcançar pontos distantes, mas frágil demais para servir como arma."},
  {"id":"alaude-elfico","nome":"Alaúde Élfico","cat":"Ferramentas","tipo":"Ferramenta","preco":300,"esp":1,"desc":"Feito com madeira de alta qualidade e manufatura delicada, este alaúde gera notas vívidas e emocionantes. Enquanto empunha este item, você pode usar a habilidade Inspiração como uma ação de movimento. Conta como um instrumento musical."},
  {"id":"colecao-livros","nome":"Coleção de Livros","cat":"Ferramentas","tipo":"Ferramenta","preco":75,"esp":1,"desc":"Uma pequena coleção de tomos e tratados sobre um assunto. Fornece +1 em Conhecimento, Guerra, Misticismo, Nobreza ou Religião (definido quando o item é comprado ou fabricado)."},
  {"id":"equipamento-viagem","nome":"Equipamento de Viagem","cat":"Ferramentas","tipo":"Ferramenta","preco":10,"esp":1,"desc":"Um saco de lona contendo instrumentos úteis para sobreviver nos ermos, como pederneira (pedra para fazer fogo), panelas e talheres para cozinhar, anzól e linha para pescar e uma pequena pá. Um personagem sem este item sofre –5 em testes de Sobrevivência para fazer um acampamento. Não inclui saco de dormir ou barraca."},
  {"id":"estojo-disfarces","nome":"Estojo de Disfarces","cat":"Ferramentas","tipo":"Ferramenta","preco":50,"esp":1,"desc":"Um conjunto de cosméticos, tintas para cabelo e algumas próteses simples (como bigodes e narizes falsos). Um personagem sem este item sofre –5 em testes de Enganação para disfarce."},
  {"id":"flauta-mistica","nome":"Flauta Mística","cat":"Ferramentas","tipo":"Ferramenta","preco":150,"esp":1,"desc":"Um instrumento delicado, repleto de runas e pequenas gemas místicas. Um bardo que empunhe este item aumenta a CD para resistir às magias lançadas por ele em +1. Conta como um instrumento musical."},
  {"id":"gazua","nome":"Gazua","cat":"Ferramentas","tipo":"Ferramenta","preco":5,"esp":1,"desc":"Uma barra fina de ferro, com a ponta torta ou em forma de gancho. Um personagem sem este item sofre –5 em testes de Ladinagem para abrir fechaduras."},
  {"id":"instrumentos-oficio","nome":"Instrumentos de Ofício","cat":"Ferramentas","tipo":"Ferramenta","preco":30,"esp":1,"desc":"Existe uma versão deste item para cada perícia de Ofício. Por exemplo, martelo, pregos e serrote para Ofício (carpinteiro), pergaminhos em branco, tinta e pena para Ofício (escriba) e assim por diante. Um personagem sem os instrumentos de seu Ofício sofre –5 nessa perícia."},
  {"id":"instrumento-musical","nome":"Instrumento Musical","cat":"Ferramentas","tipo":"Ferramenta","preco":35,"esp":1,"desc":"Um instrumento típico, como um bandolim, flauta ou lira."},
  {"id":"luneta","nome":"Luneta","cat":"Ferramentas","tipo":"Ferramenta","preco":100,"esp":1,"desc":"Este instrumento valioso consiste de um cilindro metálico com duas lentes. Fornece +5 em testes de Percepção para observar coisas em alcance longo ou além."},
  {"id":"maleta-medicamentos","nome":"Maleta de Medicamentos","cat":"Ferramentas","tipo":"Ferramenta","preco":50,"esp":1,"desc":"Caixa de madeira com ervas, unguentos, bandagens e outros materiais úteis. Um personagem sem este item sofre –5 em Cura."},
  {"id":"sela","nome":"Sela","cat":"Ferramentas","tipo":"Ferramenta","preco":20,"esp":1,"desc":"Uma peça de couro e pelego colocada sobre o lombo da montaria, sobre a qual o cavaleiro se senta. Inclui arreios para conduzir o animal. Um personagem montado em uma montaria sem sela sofre –5 em testes de Cavalgar. Usada no animal, a sela não ocupa espaço de carga do personagem."},
  {"id":"tambor-profundezas","nome":"Tambor das Profundezas","cat":"Ferramentas","tipo":"Ferramenta","preco":80,"esp":1,"desc":"Um instrumento típico de anões de Doherimm, capaz de sons graves e retumbantes. Enquanto empunha este item, o alcance da habilidade Inspiração e de qualquer Música de Bardo é dobrado. Conta como um instrumento musical."},
  {"id":"chapeu-arcano","nome":"Chapéu Arcano","cat":"Vestuário","tipo":"Vestuário","preco":50,"esp":1,"desc":"Com pinturas e bordados de símbolos místicos, este chapéu pontudo ajuda a canalizar energias mágicas. Ele fornece +1 ponto de mana, mas apenas se você possuir a habilidade de classe Caminho do Arcanista."},
  {"id":"enfeite-elmo","nome":"Enfeite de Elmo","cat":"Vestuário","tipo":"Vestuário","preco":15,"esp":1,"desc":"Um adorno chamativo, como crina de cavalo, plumas, asas ou um totem de animal. Fornece resistência a medo +2."},
  {"id":"farrapos-ermitao","nome":"Farrapos de Ermitão","cat":"Vestuário","tipo":"Vestuário","preco":1,"esp":1,"desc":"Trapos “adornados” com plantas e raízes. Uma pessoa vestindo farrapos de ermitão não parece muito civilizada, e sofre –2 em Diplomacia e em testes de Investigação para interrogar. Entretanto, recebe +2 em Adestramento."},
  {"id":"gorro-ervas","nome":"Gorro de Ervas","cat":"Vestuário","tipo":"Vestuário","preco":75,"esp":1,"desc":"Formado por duas camadas de tecido, este chapéu é preenchido com ervas preparadas para auxiliar a concentração do usuário. Fornece +1 em Vontade."},
  {"id":"luva-pelica","nome":"Luva de Pelica","cat":"Vestuário","tipo":"Vestuário","preco":5,"esp":1,"desc":"Estas luvas delicadas preservam o tato e impedem que o suor deixe os dedos escorregadios. Fornecem +1 em Ladinagem."},
  {"id":"manopla","nome":"Manopla","cat":"Vestuário","tipo":"Vestuário","preco":10,"esp":1,"desc":"Luva metálica que permite socos mais perigosos — o dano de seus ataques desarmados torna-se letal. Uma manopla conta como uma arma para receber melhorias e encantos para usá-los em seus ataques desarmados."},
  {"id":"manto-camuflado","nome":"Manto Camuflado","cat":"Vestuário","tipo":"Vestuário","preco":12,"esp":1,"desc":"Um manto camuflado é feito para um tipo de terreno específico (veja a habilidade Explorador, na página 51). Por exemplo, um manto camuflado para floresta pode ser verde e marrom e coberto de folhas, enquanto um manto urbano pode ser cinza ou negro. Usar um manto camuflado no terreno correto fornece +2 em Furtividade."},
  {"id":"manto-eclesiastico","nome":"Manto Eclesiástico","cat":"Vestuário","tipo":"Vestuário","preco":20,"esp":1,"desc":"Um manto típico de igrejas e templos. Fornece +1 em Religião."},
  {"id":"robe-mistico","nome":"Robe Místico","cat":"Vestuário","tipo":"Vestuário","preco":50,"esp":1,"desc":"Um manto longo, adornado com temas arcanos. Fornece +1 em Misticismo."},
  {"id":"sapatos-camurca","nome":"Sapatos de Camurça","cat":"Vestuário","tipo":"Vestuário","preco":8,"esp":1,"desc":"Leves e resistentes, aprimoram o equilíbrio e a firmeza dos pés, fornecendo +1 em Acrobacia."},
  {"id":"tabardo","nome":"Tabardo","cat":"Vestuário","tipo":"Vestuário","preco":10,"esp":1,"desc":"Uma peça de tecido usada como um colete, cobrindo o peito e as costas. Geralmente ostenta a heráldica de um reino, igreja, casa nobre ou ordem de cavaleiros. Fornece +1 em Diplomacia."},
  {"id":"traje-corte","nome":"Traje da Corte","cat":"Vestuário","tipo":"Vestuário","preco":100,"esp":1,"desc":"Roupas de luxo, feitas sob medida e adequadas à nobreza e realeza. Inclui algumas joias, como aneis e colares. Em certos ambientes (um baile, um salão de palácio), um personagem que não esteja vestindo este item sofre –5 em perícias baseadas em Carisma."},
  {"id":"traje-viajante","nome":"Traje de Viajante","cat":"Vestuário","tipo":"Vestuário","preco":10,"esp":0,"desc":"Inclui botas, calças ou saias, cinto, camisa de linho e capa com capuz. A roupa padrão de aventureiros."},
  {"id":"veste-seda","nome":"Veste de Seda","cat":"Vestuário","tipo":"Vestuário","preco":25,"esp":1,"desc":"Esta roupa leve e elegante deixa seus movimentos os mais livres possíveis. Fornece +1 em Reflexos."},
  {"id":"andrajos-aldeao","nome":"Andrajos de Aldeão","cat":"Vestuário","tipo":"Vestuário","preco":1,"esp":1,"desc":"Roupas típicas de camponês. Consiste de camisa larga e calças soltas ou blusa e saia e não inclui botas — os mais pobres andam descalços. Fornece +2 em testes de Investigação para interrogar (ninguém se importa com o que um aldeão escuta) e, se você possuir o poder Aparência Inofensiva, a CD para resistir a ele aumenta em +2. Porém, impõe –2 em perícias baseadas em Carisma contra pessoas que se importam com classe social."},
  {"id":"bandana","nome":"Bandana","cat":"Vestuário","tipo":"Vestuário","preco":5,"esp":1,"desc":"Um lenço tipicamente usado por bandidos e piratas. Fornece +1 em Intimidação."},
  {"id":"botas-reforcadas","nome":"Botas Reforçadas","cat":"Vestuário","tipo":"Vestuário","preco":20,"esp":1,"desc":"Grossas e resistentes, estas botas de cano alto protegem contra perigos do terreno. Aumentam seu deslocamento em +1,5m se ele for reduzido por terreno difícil (após a redução)."},
  {"id":"camisa-bufante","nome":"Camisa Bufante","cat":"Vestuário","tipo":"Vestuário","preco":25,"esp":1,"desc":"Blusa colorida, com mangas e golas longas e encrespadas. Fornece +1 em Atuação."},
  {"id":"capa-esvoacante","nome":"Capa Esvoaçante","cat":"Vestuário","tipo":"Vestuário","preco":25,"esp":1,"desc":"Favorita entre heróis ousados, esta capa de seda produz movimentos amplos e chamativos, que fornecem +1 em Enganação."},
  {"id":"capa-pesada","nome":"Capa Pesada","cat":"Vestuário","tipo":"Vestuário","preco":15,"esp":1,"desc":"Uma capa de couro grossa e resistente. Protege e aquece o corpo, fornecendo +1 em Fortitude."},
  {"id":"casaco-longo","nome":"Casaco Longo","cat":"Vestuário","tipo":"Vestuário","preco":20,"esp":1,"desc":"Feito de peles ou couro grosso forrado com lã, e impermeabilizado com óleo, este casaco é quente e pesado. Fornece +5 em testes de Fortitude para resistir a efeitos de frio, mas impõe penalidade de armadura de –2."},
  {"id":"bolsa-po","nome":"Bolsa de Pó","cat":"Esotéricos","tipo":"Esotérico","preco":300,"esp":1,"desc":"Uma bolsa com pó multicolorido, fabricado a partir das pétalas trituradas de flores que nascem apenas na Pondsmânia. Quando lança uma magia de encantamento ou ilusão, você recebe +2 PM para gastar em aprimoramentos."},
  {"id":"cajado-arcano","nome":"Cajado Arcano","cat":"Esotéricos","tipo":"Esotérico","preco":1000,"esp":2,"desc":"Um cajado típico, feito de madeira de boa qualidade e entalhado com runas. O limite de PM que você pode gastar em magias arcanas e a CD para resistir a elas aumentam em +1. Para fornecer seus benefícios, um cajado precisa ser empunhado com as duas mãos. Ele pode ser usado como arma, com as estatísticas de um bordão."},
  {"id":"cetro-elemental","nome":"Cetro Elemental","cat":"Esotéricos","tipo":"Esotérico","preco":750,"esp":1,"desc":"Este cetro possui uma pedra preciosa em sua ponta: esmeralda (ácido), topázio (eletricidade), rubi (fogo) ou safira (frio). Quando lança uma magia que causa dano do tipo da pedra, o dano aumenta em um dado do mesmo tipo."},
  {"id":"costela-lich","nome":"Costela de Lich","cat":"Esotéricos","tipo":"Esotérico","preco":300,"esp":1,"desc":"Esta varinha é feita a partir do osso de um morto-vivo. Quando lança uma magia, ela causa +1d6 pontos de dano de trevas. Se estiver empunhando esta varinha você não recupera PV por efeitos mágicos de cura."},
  {"id":"dedo-ente","nome":"Dedo de Ente","cat":"Esotéricos","tipo":"Esotérico","preco":200,"esp":1,"desc":"Uma varinha feita da madeira de uma árvore senciente. Sempre que gastar pelo menos 1 PM para lançar uma magia, role 1d4. Com um resultado 4, você recupera 1 PM."},
  {"id":"luva-ferro","nome":"Luva de Ferro","cat":"Esotéricos","tipo":"Esotérico","preco":150,"esp":1,"desc":"Um conjunto de dedais interligados por correntes. Suas magias arcanas pessoais que concedem bônus na Defesa ou em testes de resistências têm esse bônus aumentado em +1."},
  {"id":"medalhao-prata","nome":"Medalhão de Prata","cat":"Esotéricos","tipo":"Esotérico","preco":750,"esp":1,"desc":"Gravado com uma runa pessoal do conjurador, este medalhão de prata diminui em –1 PM o custo de magias de alcance pessoal."},
  {"id":"orbe-cristalino","nome":"Orbe Cristalino","cat":"Esotéricos","tipo":"Esotérico","preco":750,"esp":1,"desc":"Esta esfera perfeita concentra seu poder mágico. O limite de PM que você pode gastar em magias arcanas aumenta em +1."},
  {"id":"tomo-hermetico","nome":"Tomo Hermético","cat":"Esotéricos","tipo":"Esotérico","preco":1500,"esp":1,"desc":"Um livro de tratados que aumentam a sua compreensão sobre uma escola de magia específica. A CD para resistir a suas magias arcanas dessa escola aumenta em +2."},
  {"id":"varinha-arcana","nome":"Varinha Arcana","cat":"Esotéricos","tipo":"Esotérico","preco":100,"esp":1,"desc":"Uma varinha típica, feita de madeira de boa qualidade e entalhada com runas. A CD para resistir a suas magias arcanas aumenta em +1."},
  {"id":"acido","nome":"Ácido","cat":"Alquímicos — Preparados","tipo":"Alquímico","preco":10,"esp":0.5,"desc":"Frasco de vidro contendo um ácido alquímico altamente corrosivo. Para usar o ácido, você gasta uma ação padrão e escolhe uma criatura em alcance curto. Essa criatura sofre 2d4 pontos de dano de ácido (Reflexos CD Des reduz à metade)."},
  {"id":"balsamo-restaurador","nome":"Bálsamo Restaurador","cat":"Alquímicos — Preparados","tipo":"Alquímico","preco":10,"esp":0.5,"desc":"Uma pasta verde e fedorenta, feita de ervas medicinais. Usá-la é uma ação completa e recupera 2d4 pontos de vida."},
  {"id":"bomba","nome":"Bomba","cat":"Alquímicos — Preparados","tipo":"Alquímico","preco":50,"esp":0.5,"desc":"Uma granada rudimentar. Para usar a bomba, você precisa empunhá-la, gastar uma ação de movimento para acender seu pavio e uma ação padrão para arremessá-la em um ponto em alcance curto. Criaturas a até 3m desse ponto sofrem 6d6 pontos de dano de impacto (Reflexos CD Des reduz à metade)."},
  {"id":"cosmetico","nome":"Cosmético","cat":"Alquímicos — Preparados","tipo":"Alquímico","preco":30,"esp":0.5,"desc":"Perfume ou maquiagem. Usá-lo é uma ação completa e fornece +2 em testes de perícias baseadas em Carisma até o fim da cena."},
  {"id":"elixir-amor","nome":"Elixir do Amor","cat":"Alquímicos — Preparados","tipo":"Alquímico","preco":100,"esp":0.5,"desc":"Um humanoide que beba este líquido adocicado fica apaixonado pela primeira criatura que enxergar (condição enfeitiçado; Vontade CD Car anula). O efeito dura 1d3 dias."},
  {"id":"essencia-mana","nome":"Essência de Mana","cat":"Alquímicos — Preparados","tipo":"Alquímico","preco":50,"esp":0.5,"desc":"Esta poção feita de ervas raras e compostos alquímicos recupera energia pessoal. Beber a essência de mana é uma ação padrão e recupera 1d4 pontos de mana."},
  {"id":"fogo-alquimico","nome":"Fogo Alquímico","cat":"Alquímicos — Preparados","tipo":"Alquímico","preco":10,"esp":0.5,"desc":"Frasco de cerâmica contendo uma substância que entra em combustão em contato com o ar. Para usar o fogo alquímico, você gasta uma ação padrão e escolhe uma criatura em alcance curto. Essa criatura sofre 1d6 pontos de dano de fogo e fica em chamas. Um teste de Reflexos (CD Des) reduz o dano à metade e evita as chamas."},
  {"id":"po-desaparecimento","nome":"Pó do Desaparecimento","cat":"Alquímicos — Preparados","tipo":"Alquímico","preco":100,"esp":0.5,"desc":"Uma criatura ou objeto coberto por este pó torna-se invisível (como em Invisibilidade) por 2d6 rodadas. O usuário não sabe quando a invisibilidade vai terminar."},
  {"id":"baga-fogo","nome":"Baga-de-Fogo","cat":"Alquímicos — Catalisadores","tipo":"Catalisador","preco":30,"esp":0.5,"desc":"Pequeno fruto vermelho, apreciado por seu sabor picante. Usado como catalisador, adiciona +1d6 de dano de fogo a magias."},
  {"id":"dente-dragao","nome":"Dente-de-Dragão","cat":"Alquímicos — Catalisadores","tipo":"Catalisador","preco":45,"esp":0.5,"desc":"Uma flor comum em regiões montanhosas, especialmente nas Sanguinárias, possui formato parecido com uma presa de monstro. Suas propriedades místicas aumentam o dano de magias em um dado do mesmo tipo."},
  {"id":"essencia-abissal","nome":"Essência Abissal","cat":"Alquímicos — Catalisadores","tipo":"Catalisador","preco":150,"esp":0.5,"desc":"Um líquido espesso, produzido através do sangue de criaturas demoníacas. Aumenta os dados de dano de magias de fogo em uma categoria — d4 para d6, d6 para d8, d8 para d10 e d10 para d12 (o máximo)."},
  {"id":"liquen-lilas","nome":"Líquen Lilás","cat":"Alquímicos — Catalisadores","tipo":"Catalisador","preco":30,"esp":0.5,"desc":"Esta estranha planta tem aspecto cristalino e cresce em abundância na região das Uivantes. Adiciona +1d6 de dano de frio a magias."},
  {"id":"musgo-purpura","nome":"Musgo Púrpura","cat":"Alquímicos — Catalisadores","tipo":"Catalisador","preco":45,"esp":0.5,"desc":"Encontrado em florestas fechadas, esse fungo cintilante possui propriedades que fornecem +2 na CD de magias de ilusão."},
  {"id":"ossos-monstro","nome":"Ossos de Monstro","cat":"Alquímicos — Catalisadores","tipo":"Catalisador","preco":45,"esp":0.5,"desc":"Pequenas falanges de criaturas monstruosas, tratadas com óleos alquímicos. Fornece +2 na CD de magias de necromancia."},
  {"id":"po-cristal","nome":"Pó de Cristal","cat":"Alquímicos — Catalisadores","tipo":"Catalisador","preco":30,"esp":0.5,"desc":"Uma pitada de pó de um mineral cristalino puro, como quartzo ou topázio. Diminui o custo de magias de encantamento em –1 PM."},
  {"id":"po-giz","nome":"Pó de Giz","cat":"Alquímicos — Catalisadores","tipo":"Catalisador","preco":30,"esp":0.5,"desc":"Calcário esmagado em pó, uma substância comum que, usada como catalisador, diminui o custo de magias de convocação em –1 PM."},
  {"id":"ramo-verdejante","nome":"Ramo Verdejante","cat":"Alquímicos — Catalisadores","tipo":"Catalisador","preco":45,"esp":0.5,"desc":"Esta combinação de ervas potencializa magias de cura, aumentando sua cura em +1 PV por dado."},
  {"id":"saco-sal","nome":"Saco de Sal","cat":"Alquímicos — Catalisadores","tipo":"Catalisador","preco":45,"esp":0.5,"desc":"Um pequeno saco de couro com sal marinho. Fornece +2 na CD de magias de abjuração."},
  {"id":"seixo-ambar","nome":"Seixo de Âmbar","cat":"Alquímicos — Catalisadores","tipo":"Catalisador","preco":30,"esp":0.5,"desc":"Essa “gema” feita de seiva de árvore fossilizada diminui o custo de magias de transmutação em –1 PM."},
  {"id":"terra-cemiterio","nome":"Terra de Cemitério","cat":"Alquímicos — Catalisadores","tipo":"Catalisador","preco":30,"esp":0.5,"desc":"Um punhado de terra cinzenta, colhida à noite de um cemitério. Adiciona +1d6 de dano de trevas a magias."},
  {"id":"beladona","nome":"Beladona","cat":"Alquímicos — Venenos","tipo":"Veneno","preco":1500,"esp":0.5,"desc":"Planta extremamente tóxica que afeta o sistema nervoso da vítima. Ingestão, vítima fica paralisada (lenta) por 3 rodadas. A CD para fabricar e para resistir a este veneno aumenta em +5."},
  {"id":"bruma-sonolenta","nome":"Bruma Sonolenta","cat":"Alquímicos — Venenos","tipo":"Veneno","preco":150,"esp":0.5,"desc":"Um gás sonífero. Inalação, vítima fica inconsciente (enjoada por 1 rodada)."},
  {"id":"cicuta","nome":"Cicuta","cat":"Alquímicos — Venenos","tipo":"Veneno","preco":60,"esp":0.5,"desc":"Planta cuja ingestão pode causar náusea, dores e até morte. Ingestão, perde 1d12 PV por rodada durante 3 rodadas (perde 1d12 PV)."},
  {"id":"essencia-sombra","nome":"Essência de Sombra","cat":"Alquímicos — Venenos","tipo":"Veneno","preco":100,"esp":0.5,"desc":"Produzido a partir de compostos alquímicos que canalizam energia de trevas. Contato, vítima fica debilitada (fraca)."},
  {"id":"nevoa-toxica","nome":"Névoa Tóxica","cat":"Alquímicos — Venenos","tipo":"Veneno","preco":30,"esp":0.5,"desc":"Este gás verde queima e corrói a pele e os pulmões. Inalação, perde 1d12 PV por rodada durante 3 rodadas (perde 1d12 PV)."},
  {"id":"peconha-comum","nome":"Peçonha Comum","cat":"Alquímicos — Venenos","tipo":"Veneno","preco":15,"esp":0.5,"desc":"Veneno típico, extraído de animais ou plantas tóxicas. Contato, perde 1d12 PV."},
  {"id":"peconha-concentrada","nome":"Peçonha Concentrada","cat":"Alquímicos — Venenos","tipo":"Veneno","preco":90,"esp":0.5,"desc":"Dose concentrada da peçonha comum. Contato, perde 1d12 PV por rodada durante 3 rodadas (perde 1d12 PV)."},
  {"id":"peconha-potente","nome":"Peçonha Potente","cat":"Alquímicos — Venenos","tipo":"Veneno","preco":600,"esp":0.5,"desc":"Veneno poderoso, extraído de animais ou plantas perigosos. Contato, perde 2d12 PV por rodada durante 3 rodadas (perde 2d12 PV)."},
  {"id":"po-lich","nome":"Pó de Lich","cat":"Alquímicos — Venenos","tipo":"Veneno","preco":3000,"esp":0.5,"desc":"Veneno letal, usado para assassinar alvos poderosos. Ingestão, perde 4d12 PV por rodada durante 5 rodadas (perde 4d12 PV). A CD para fabricar e para resistir a este veneno aumenta em +5."},
  {"id":"riso-nimb","nome":"Riso de Nimb","cat":"Alquímicos — Venenos","tipo":"Veneno","preco":150,"esp":0.5,"desc":"Este gás púrpura faz a vítima rir descontroladamente e agir de forma caótica. Inalação, vítima fica confusa (lenta por 1 rodada)."},
  {"id":"batata-valkariana","nome":"Batata Valkariana","cat":"Alimentação","tipo":"Alimentação","preco":2,"esp":0.5,"desc":"Batatas cortadas em tiras e mergulhadas em óleo fervente. Gordurentas e pouco nutritivas, são o tipo de prato que só é servido numa metrópole como Valkaria. Apesar disso, são gostosas e deixam qualquer um empolgado. Você recebe +1d6 em um teste a sua escolha realizado até o fim do dia. Para não esquecer, deixe 1d6 em cima da sua ficha. De preferência, amarelo."},
  {"id":"gorad-quente","nome":"Gorad Quente","cat":"Alimentação","tipo":"Alimentação","preco":18,"esp":0.5,"desc":"Gorad e leite, servidos quentes. Não tem erro. O gorad ativa o cérebro, fornecendo +2 PM temporários."},
  {"id":"macarrao-yuvalin","nome":"Macarrão de Yuvalin","cat":"Alimentação","tipo":"Alimentação","preco":6,"esp":0.5,"desc":"Yuvalin é uma cidade mineradora em Zakharov, na fronteira com as Montanhas Uivantes. Seus habitantes criaram este prato reforçado (macarrão, bacon e creme de leite!) para encarar suas árduas jornadas de trabalho nas minas. Delicioso, o prato se espalhou por outras cidades e reinos. Você recebe +5 PV temporários."},
  {"id":"prato-aventureiro","nome":"Prato do Aventureiro","cat":"Alimentação","tipo":"Alimentação","preco":1,"esp":0.5,"desc":"Um cozido de galinha com legumes, esta é uma refeição simples, mas nutritiva. Em sua próxima noite de sono, você aumenta a sua recuperação de pontos de vida em +1 por nível."},
  {"id":"racao-viagem","nome":"Ração de Viagem (por dia)","cat":"Alimentação","tipo":"Alimentação","preco":0.5,"esp":0.5,"desc":"Própria para viagens, uma porção desta ração alimenta uma pessoa por um dia. É feita de alimentos conservados, como carne defumada, frutas secas, pão, queijo e biscoitos. Se mantida seca dura bastante, mas quando molhada se estraga em 24 horas."},
  {"id":"refeicao-comum","nome":"Refeição Comum","cat":"Alimentação","tipo":"Alimentação","preco":0.3,"esp":0.5,"desc":"Uma refeição típica inclui pão, queijo, cozido de carne ou galinha com legumes e uma caneca de bebida, geralmente cidra, vinho ou cerveja."},
  {"id":"sopa-peixe","nome":"Sopa de Peixe","cat":"Alimentação","tipo":"Alimentação","preco":1,"esp":0.5,"desc":"Um cozido de peixe com verduras. É um prato humilde, mas garante um descanso relaxante. Em sua próxima noite de sono, você aumenta a sua recuperação de pontos de mana em +1 por nível."},
  {"id":"alforje","nome":"Alforje","cat":"Animais","tipo":"Animal","preco":30,"esp":0,"desc":"Sacos de couro feitos para serem presos em uma sela. Permitem que um parceiro montaria carregue até 10 espaços de item para você."},
  {"id":"cao-caca","nome":"Cão de Caça","cat":"Animais","tipo":"Animal","preco":150,"esp":0,"desc":"Este cachorro valente e leal pode ser usado como parceiro perseguidor por personagens treinados em Adestramento ou montaria por personagens Pequenos e Minúsculos."},
  {"id":"cavalo","nome":"Cavalo","cat":"Animais","tipo":"Animal","preco":75,"esp":0,"desc":"A montaria mais comum no Reinado. Pode ser usado como parceiro montaria (veja a página 262). Cavalos sem treinamento se assustam facilmente, sendo necessário um teste de Cavalgar (CD 20) por rodada para permanecer montado durante um combate. Cavalos de guerra dispensam esse teste. Estábulo. Inclui alimentação para o animal."},
  {"id":"cavalo-guerra","nome":"Cavalo de Guerra","cat":"Animais","tipo":"Animal","preco":400,"esp":0,"desc":"Cavalos de guerra dispensam o teste de Cavalgar (CD 20) por rodada para permanecer montado durante um combate."},
  {"id":"ponei","nome":"Pônei","cat":"Animais","tipo":"Animal","preco":5,"esp":0,"desc":"A montaria mais comum entre raças Pequenas. Pode ser usado como parceiro montaria."},
  {"id":"ponei-guerra","nome":"Pônei de Guerra","cat":"Animais","tipo":"Animal","preco":30,"esp":0,"desc":""},
  {"id":"trobo","nome":"Trobo","cat":"Animais","tipo":"Animal","preco":60,"esp":0,"desc":"Estas enormes aves, também chamadas de pássaros-touros, são parecidas com avestruzes com chifres, couro e cascos. Não têm asas. Possuem poucas penas, que servem apenas como ornamento. Muito dóceis, trobos são usados em áreas rurais como animais de carga e tração, mas também podem ser usados como montaria (veja a página 262)."},
  {"id":"balao-goblin","nome":"Balão Goblin","cat":"Veículos","tipo":"Veículo","preco":200,"esp":0,"desc":"Feito de imensas bolsas de couro e outros tecidos remendados, com uma gôndola parecida com um grande cesto, o balão goblin é um engenho tecnológico sem igual em Arton. Um balão tem tamanho Enorme, deslocamento voo 12m, Defesa 5 (+ Des do baloeiro), 100 PV e pode carregar até 8 criaturas Médias ou 160 espaços. Ao contrário do que possa parecer, quedas de balões raramente são fatais. Quando o balão perde mais da metade de seus PV, começa a perder ar e flutua lentamente na direção do solo. Cada ocupante sofre 4d6 pontos de dano de impacto (Ref CD 15 reduz à metade). Um balão só cai de forma perigosa caso perca todos os seus PV. Neste caso, os ocupantes sofrem dano normal pela queda, de acordo com a altura. Remendar um balão em pleno voo exige uma ação completa e um teste de Ofício (artesão) contra CD 15. Se você passar no teste, recupera 1d8 PV do balão."},
  {"id":"carroca","nome":"Carroça","cat":"Veículos","tipo":"Veículo","preco":150,"esp":0,"desc":"Veículo de duas ou quatro rodas, aberto, normalmente usado para transportar cargas pesadas. É puxada por dois cavalos ou um trobo. Inclui os arreios necessários para controlar os animais. Uma carroça tem tamanho Grande, deslocamento 9m, Defesa 8 (+ Des do condutor), 50 PV e pode carregar até 4 criaturas Médias ou 80 espaços."},
  {"id":"carruagem","nome":"Carruagem","cat":"Veículos","tipo":"Veículo","preco":500,"esp":0,"desc":"Veículo de quatro rodas, capaz de transportar até quatro pessoas em uma cabine fechada, mais dois condutores do lado de fora. É puxada por dois cavalos ou um trobo. Inclui os arreios necessários para controlar os animais. Tem as mesmas estatísticas de uma carroça, mas fornece cobertura leve a seus passageiros."},
  {"id":"canoa","nome":"Canoa","cat":"Veículos","tipo":"Veículo","preco":70,"esp":0,"desc":"Construída a partir de um único tronco de árvore, é a mais simples das embarcações. Tem as mesmas estatísticas de uma carroça, mas com deslocamento de natação."},
  {"id":"veleiro","nome":"Veleiro","cat":"Veículos","tipo":"Veículo","preco":10000,"esp":0,"desc":"Com três mastros, é o típico navio de viagem, muito popular entre mercadores."}
];
